import pytest

from bedrock_protocol import v2225

# generated by gophertunnel b8bd735:
# &packet.LessonProgress{Identifier: "chemistry.intro", Action: packet.LessonActionComplete, Score: 300}
COMPLETE = bytes.fromhex("02d8040f6368656d69737472792e696e74726f")

# generated by gophertunnel b8bd735:
# &packet.LessonProgress{Identifier: "", Action: packet.LessonActionRestart, Score: -1}
RESTART = bytes.fromhex("040100")

GOLDENS = [
    pytest.param(
        v2225.LessonProgressPacket(action=v2225.LessonAction.COMPLETE, score=300, activity_id="chemistry.intro"),
        COMPLETE,
        id="complete",
    ),
    pytest.param(
        v2225.LessonProgressPacket(action=v2225.LessonAction.RESTART, score=-1, activity_id=""),
        RESTART,
        id="restart-with-a-negative-score",
    ),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_lesson_progress_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_lesson_progress_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
